import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Carousel } from "react-responsive-carousel";
import "react-responsive-carousel/lib/styles/carousel.min.css";

function Creative() {
  const navigate = useNavigate();
  const [isVideoOpen, setIsVideoOpen] = useState(false);

  const images1 = ["/creativec11.avif", "/creativec12.avif", "/creativec13.avif"];
  const images2 = ["/creativec21.avif", "/creaticec22.avif"];

  return (
    <>
      {/* Go Back Button */}
      <p
        className="underline text-base sm:text-lg md:text-xl lg:text-l cursor-pointer pl-5"
        onClick={() => navigate(-1)}
      >
        Go Back
      </p>

      {/* Heading Section */}
      <div className="flex flex-col items-center justify-center mt-5ßßß">
        <h2 className="text-5xl font-bold text-red-500 text-center mt-5 mb-40">Other Works</h2>
      </div>

      {/* Video Section */}
      <div className="flex flex-col items-center mt-30 w-full px-4">
        {/* Video 1 */}
        <div className="w-full max-w-3xl relative">
          <h2 className="text-3xl font-bold text-black text-center mt-20 mb-20">
            Foley - Sound Design
          </h2>
          <div
            className="relative w-full h-[180px] sm:h-[250px] md:h-[300px] lg:h-[350px] bg-cover bg-center cursor-pointer flex items-center justify-center mb-10"
            style={{ backgroundImage: "url('/kalpana.avif')" }}
            onClick={() => setIsVideoOpen(true)}
          ></div>
        </div>

        {/* Video 2 */}
        <div className="w-full max-w-3xl relative ">
          <h2 className="text-3xl font-bold text-black text-centermt-20 mt-20 mb-6">
            Representation of liquid through multi-sensory visualization.
          </h2>
          <div
            className="relative w-full h-[180px] sm:h-[250px] md:h-[300px] lg:h-[350px] bg-cover bg-center cursor-pointer flex items-center justify-center mb-10"
            style={{ backgroundImage: "url('/kalpana.avif')" }}
            onClick={() => setIsVideoOpen(true)}
          ></div>
        </div>
      </div>

      {/* Carousel Section */}
      <h2 className="text-3xl text-black text-center mt-10">The Product</h2>

      <div className="flex flex-col md:flex-row justify-center items-center gap-6 mt-6 px-4">
        {/* Carousel 1 */}
        <div className="w-full md:w-1/2">
          <Carousel
            autoPlay
            infiniteLoop
            showThumbs={false}
            showStatus={false}
            interval={3000}
          >
            {images1.map((image, index) => (
              <div key={index}>
                <img src={image} alt={`Product Slide ${index + 1}`} className="rounded-lg" />
              </div>
            ))}
          </Carousel>
        </div>

        {/* Carousel 2 */}
        <div className="w-full md:w-1/2">
          <Carousel
            autoPlay
            infiniteLoop
            showThumbs={false}
            showStatus={false}
            interval={3000}
          >
            {images2.map((image, index) => (
              <div key={index}>
                <img src={image} alt={`Design Slide ${index + 1}`} className="rounded-lg" />
              </div>
            ))}
          </Carousel>
        </div>
      </div>

      <br />
      <br />
      <br />
    </>
  );
}

export default Creative;
